# Generate everything that has to agree with the rename register.
#
#   julia --project=. scripts/generate_renames.jl
#
# Reads scripts/renames.jl and writes
#
#   src/public_names.jl        the `public` declaration (§13.1)
#   src/audit_names.jl         the name sets src/audit.jl matches against
#
# Neither file is edited by hand.

include(joinpath(@__DIR__, "renames.jl"))

const ROOT = normpath(joinpath(@__DIR__, ".."))

const HEADER = """
# This file is generated by scripts/generate_renames.jl from scripts/renames.jl.
# Do not edit it: edit the register and regenerate.
"""

# ---------------------------------------------------------------------------
# Consistency checks
# ---------------------------------------------------------------------------

function check_register()
    olds = first.(RENAMES)
    length(unique(olds)) == length(olds) ||
        error("duplicate old name in RENAMES: $(filter(n -> count(==(n), olds) > 1, unique(olds)))")
    news = Set(last.(RENAMES))
    for n in news
        n in INTERNAL &&
            error("$n is both a rename target and internal")
    end
    for n in UNCHANGED_PUBLIC
        n in olds && error("$n is both unchanged and renamed")
        n in INTERNAL && error("$n is both unchanged-public and internal")
    end
    return nothing
end

# The `public` list: every new name plus every unchanged public name, minus the
# ones Base owns and the ones that are exported (a name cannot be both).
function public_names()
    names = Symbol[]
    for (_, new) in RENAMES
        new in BASE_TARGETS && continue
        push!(names, new)
    end
    append!(names, UNCHANGED_PUBLIC)
    exported = Set(EXPORTED)
    return sort!(unique!(filter(n -> !(n in exported), names)); by = String)
end

# ---------------------------------------------------------------------------
# src/public_names.jl
# ---------------------------------------------------------------------------

function write_public(path)
    io = IOBuffer()
    print(io, HEADER)
    print(
        io,
        """
#
# The high-level API that is not exported (docs/src/man/naming.md §13.1).
# Julia 1.12 is the minimum supported version, so this is unconditional.

""",
    )
    names = public_names()
    # `public` takes a comma-separated list; wrap it so the file stays readable.
    line = "public "
    for (i, n) in enumerate(names)
        item = String(n) * (i == length(names) ? "" : ",")
        if length(line) + length(item) + 1 > 92
            println(io, rstrip(line))
            line = "       "
        end
        line *= (endswith(line, " ") ? "" : " ") * item
    end
    println(io, rstrip(line))
    write(path, String(take!(io)))
    return nothing
end

# ---------------------------------------------------------------------------
# src/audit_names.jl
# ---------------------------------------------------------------------------

function write_audit_names(path)
    io = IOBuffer()
    print(io, HEADER)
    print(
        io,
        """
#
# The names src/audit.jl matches against. Generated so that the next rename
# cannot blind the auditor: after a rename its patterns would otherwise stop
# matching and it would report no leaks on leaking code.

\"\"\"
    AUDIT_TYPE_CREATORS

Type constructors whose name is also the kind of object they create.
\"\"\"
""",
    )
    println(io, "const AUDIT_TYPE_CREATORS = Dict{Symbol, String}(")
    for k in sort!(collect(keys(AUDIT_TYPE_CREATORS)); by = String)
        println(io, "    :$k => $(repr(AUDIT_TYPE_CREATORS[k])),")
    end
    println(io, ")\n")

    print(
        io,
        """
\"\"\"
    AUDIT_NAMED_CREATORS

Creators whose name carries no `Create`/`Duplicate` marker for
[`audit_creator`](@ref) to recognise by shape.
\"\"\"
""",
    )
    println(io, "const AUDIT_NAMED_CREATORS = Dict{Symbol, String}(")
    for k in sort!(collect(keys(AUDIT_NAMED_CREATORS)); by = String)
        println(io, "    :$k => $(repr(AUDIT_NAMED_CREATORS[k])),")
    end
    println(io, ")\n")

    print(
        io,
        """
\"\"\"
    AUDIT_DESTROYER_NAMES

Names that release a PETSc object. `finalizer` counts: it hands the release to
the garbage collector rather than performing it, but the object is accounted for.
\"\"\"
""",
    )
    println(
        io,
        "const AUDIT_DESTROYER_NAMES = Set{Symbol}([" *
        join((":$n" for n in AUDIT_DESTROYERS), ", ") *
        "])",
    )
    write(path, String(take!(io)))
    return nothing
end

# ---------------------------------------------------------------------------

check_register()
write_public(joinpath(ROOT, "src", "public_names.jl"))
write_audit_names(joinpath(ROOT, "src", "audit_names.jl"))
println("wrote src/public_names.jl, src/audit_names.jl")
